import { useState } from "react";

export function Hero({ title }) {
  const [n, setN] = useState(0);
  const bump = () => setN((x) => x + 1);
  return (
    <section data-testid="hero">
      <h1>{title}</h1>
      <button type="button" onClick={bump}>+</button>
      <p>{n}</p>
    </section>
  );
}
